#Requires -Version 7.4
[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][ValidateNotNullOrEmpty()][string]$ApplicationRoot,
 [switch]$AuditOnly,
 [switch]$ContinueOnNonCriticalError
)
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$ScriptName = "Application_Governance_Controls"
$ScriptVersion = "1.2.2"
$Classification = "BHP Internal"
$RunId = "APP-GOV-CONTROLS-{0}" -f (Get-Date -Format "yyyyMMdd-HHmmss")
function Assert-PathValue { param([string]$Value,[string]$Name) if([string]::IsNullOrWhiteSpace($Value)){throw ("{0} is empty." -f $Name)} if(-not [IO.Path]::IsPathFullyQualified($Value)){throw ("{0} must be absolute." -f $Name)} }
function Relative-Path { param([string]$Base,[string]$Full) return [IO.Path]::GetRelativePath([IO.Path]::GetFullPath($Base),[IO.Path]::GetFullPath($Full)) }
function Read-Text { param([string]$Path) try{return Get-Content -LiteralPath $Path -Raw -Encoding utf8 -ErrorAction Stop}catch{return $null} }
function Category { param([IO.FileInfo]$File) $n=$File.Name.ToLowerInvariant();$e=$File.Extension.ToLowerInvariant(); if($n -match "manifest|release_register|release_version"){return "MANIFEST"};if($n -match "sha256|checksum|hash"){return "HASH_REGISTER"};if($e -in @(".ps1",".psm1",".psd1",".py",".r",".cmd",".bat")){return "CODE"};if($e -in @(".json",".yml",".yaml",".toml",".xml",".config")){return "CONFIG"};return "OTHER" }
function Resolve-Ref { param([string]$Reference,[string]$SourceDirectory,[string]$Root,[object[]]$AllFiles) $r=[ordered]@{Status="UNRESOLVED";Target=$null;Method="NONE"};$c=$Reference.Trim().Trim('"').Trim("'");if([string]::IsNullOrWhiteSpace($c)){return [pscustomobject]$r};$candidates=@();if([IO.Path]::IsPathFullyQualified($c)){$candidates+= $c}else{$candidates+=(Join-Path $SourceDirectory $c);$candidates+=(Join-Path $Root $c)};foreach($p in $candidates){if(Test-Path -LiteralPath $p -PathType Leaf){$r.Status="RESOLVED";$r.Target=[IO.Path]::GetFullPath($p);$r.Method="EXACT_PATH";return [pscustomobject]$r}};$leaf=Split-Path $c -Leaf;$m=@($AllFiles|Where-Object{$_.Name -ieq $leaf});if($m.Count -eq 1){$r.Status="RESOLVED";$r.Target=$m[0].FullName;$r.Method="UNIQUE_NAME"}elseif($m.Count -gt 1){$r.Status="AMBIGUOUS";$r.Method="MULTIPLE_NAMES"};return [pscustomobject]$r }
function Dependencies { param([IO.FileInfo]$File,[string]$Root,[object[]]$AllFiles) $out=[Collections.Generic.List[object]]::new();$t=Read-Text $File.FullName;if($null -eq $t){return @($out)};$patterns=@(@{Type="FILE";Regex='(?i)["'']([^"'']+\.(?:ps1|psm1|psd1|py|r|json|yml|yaml|toml|xml|config|csv|las))["'']'},@{Type="RUNTIME";Regex='(?i)(python(?:3)?(?:\.exe)?|py(?:\.exe)?|pwsh(?:\.exe)?|powershell(?:\.exe)?|Rscript(?:\.exe)?)'});foreach($p in $patterns){foreach($m in @([regex]::Matches($t,$p.Regex))){$v=$m.Groups[1].Value;if($p.Type -eq "RUNTIME"){$runtime=$v.ToLowerInvariant().Replace(".exe","");if($runtime -in @("python3","py")){$runtime="python"};if($runtime -eq "pwsh"){$runtime="powershell"};$out.Add([pscustomobject]@{Source=$File.FullName;Reference=$v;Type="RUNTIME";Status="EXTERNAL_RUNTIME";Target=$runtime;Method="NORMALIZED"})}else{$x=Resolve-Ref $v $File.DirectoryName $Root $AllFiles;$out.Add([pscustomobject]@{Source=$File.FullName;Reference=$v;Type="FILE";Status=$x.Status;Target=$x.Target;Method=$x.Method})}}};return @($out|Sort-Object Source,Reference,Type -Unique) }
function Manifest-Entries { param([IO.FileInfo]$File) $t=Read-Text $File.FullName;if($null -eq $t){return @()};$m=[regex]::Matches($t,'(?i)["'']?([^"''\r\n,]+\.(?:ps1|psm1|psd1|py|r|json|yml|yaml|toml|xml|config|csv|md|txt|docx|xlsx|pptx|pdf|las))["'']?');return @($m|ForEach-Object{$_.Groups[1].Value.Trim()}|Sort-Object -Unique) }
function Hash-Entries { param([IO.FileInfo]$File) $t=Read-Text $File.FullName;if($null -eq $t){return @()};$o=@();foreach($m in @([regex]::Matches($t,'(?im)^\s*([A-Fa-f0-9]{64})\s+\*?\s*(.+?)\s*$'))){$o+=[pscustomobject]@{Register=$File.FullName;ExpectedSHA256=$m.Groups[1].Value.ToUpperInvariant();Reference=$m.Groups[2].Value.Trim()}};return @($o) }
Assert-PathValue $ApplicationRoot "ApplicationRoot"
if(-not(Test-Path -LiteralPath $ApplicationRoot -PathType Container)){throw ("ApplicationRoot not found: {0}" -f $ApplicationRoot)}
$ApplicationRoot=[IO.Path]::GetFullPath($ApplicationRoot).TrimEnd([IO.Path]::DirectorySeparatorChar)
$ToolRoot=Join-Path $ApplicationRoot "00_Script\Application_Governance";$InstalledTool=Join-Path $ToolRoot "Application_Governance_Controls_v1_2_2.ps1";$AuditBase=Join-Path $ApplicationRoot "_Audit\Application_Governance";$ReportRoot=Join-Path $AuditBase $RunId
$before=@(Get-ChildItem -LiteralPath $ApplicationRoot -File -Recurse -Force|Where-Object{$_.FullName -notlike ($AuditBase+"\*") -and $_.FullName -notlike ($ToolRoot+"\*")}|Sort-Object FullName|ForEach-Object{"{0}|{1}|{2:o}" -f $_.FullName,$_.Length,$_.LastWriteTimeUtc})
$files=@(Get-ChildItem -LiteralPath $ApplicationRoot -File -Recurse -Force|Sort-Object FullName);$folders=@(Get-ChildItem -LiteralPath $ApplicationRoot -Directory -Recurse -Force);$eligible=@($files|Where-Object{$_.FullName -notlike ($AuditBase+"\*")});$code=@($eligible|Where-Object{(Category $_) -in @("CODE","CONFIG")});$manifests=@($eligible|Where-Object{(Category $_) -eq "MANIFEST"});$hashRegisters=@($eligible|Where-Object{(Category $_) -eq "HASH_REGISTER"})
$deps=@();foreach($f in $code){$deps+=@(Dependencies $f $ApplicationRoot $eligible)};$deps=@($deps|Sort-Object Source,Reference,Type -Unique);$runtimes=@($deps|Where-Object{$_.Type -eq "RUNTIME"});$local=@($deps|Where-Object{$_.Type -eq "FILE"});$resolved=@($local|Where-Object{$_.Status -eq "RESOLVED"});$ambiguous=@($local|Where-Object{$_.Status -eq "AMBIGUOUS"});$unresolved=@($local|Where-Object{$_.Status -eq "UNRESOLVED"})
$mr=@();foreach($f in $manifests){foreach($e in @(Manifest-Entries $f)){$x=Resolve-Ref $e $f.DirectoryName $ApplicationRoot $eligible;$mr+=[pscustomobject]@{Manifest=$f.FullName;Entry=$e;Status=$x.Status;Target=$x.Target;Method=$x.Method}}};$manifestTargets=@($mr|Where-Object{$_.Status -eq "RESOLVED"}|Select-Object -ExpandProperty Target -Unique)
$he=@();foreach($f in $hashRegisters){$he+=@(Hash-Entries $f)};$hv=@();foreach($e in $he){$x=Resolve-Ref $e.Reference (Split-Path $e.Register -Parent) $ApplicationRoot $eligible;$actual=$null;$verification="NOT_VERIFIED";if($x.Status -eq "RESOLVED"){try{$actual=(Get-FileHash -LiteralPath $x.Target -Algorithm SHA256).Hash.ToUpperInvariant();$verification=if($actual -eq $e.ExpectedSHA256){"MATCH"}else{"MISMATCH"}}catch{$verification="HASH_ERROR"}};$hv+=[pscustomobject]@{Register=$e.Register;Reference=$e.Reference;ExpectedSHA256=$e.ExpectedSHA256;ResolutionStatus=$x.Status;Target=$x.Target;ResolutionMethod=$x.Method;ActualSHA256=$actual;Verification=$verification}}
$hashTargets=@($hv|Where-Object{$_.ResolutionStatus -eq "RESOLVED"}|Select-Object -ExpandProperty Target -Unique);$confirmedMismatch=@($hv|Where-Object{$_.Verification -eq "MISMATCH" -and $_.ResolutionMethod -eq "EXACT_PATH"})
$fileHashes=@();foreach($f in $eligible){try{$fileHashes+=[pscustomobject]@{FullName=$f.FullName;RelativePath=(Relative-Path $ApplicationRoot $f.FullName);SHA256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToUpperInvariant();Length=$f.Length}}catch{}};$dupeGroups=@($fileHashes|Group-Object SHA256|Where-Object{@($_.Group).Count -gt 1});$dupes=@();foreach($g in $dupeGroups){$members=@($g.Group);$type=if(@($members|Where-Object{$_.RelativePath -match '(?i)(backup|archive|snapshot|_audit)'}).Count -gt 0){"GOVERNED_OR_EVIDENCE_COPY"}elseif(@($members|Where-Object{$_.RelativePath -match '(?i)(copy|draft|temp|old|legacy)'}).Count -gt 0){"REVIEW_COPY"}else{"ACTIVE_DUPLICATE_REVIEW"};foreach($m in $members){$dupes+=[pscustomobject]@{SHA256=$g.Name;RelativePath=$m.RelativePath;Length=$m.Length;DuplicateType=$type}}}
$entryPoints=@($code|Where-Object{$_.Name -match '(?i)^(start|run|launch|install|main|bootstrap)' -or $_.Name -match '(?i)(launcher|entrypoint)'}|Select-Object -ExpandProperty FullName -Unique);$protected=@($resolved.Target+$manifestTargets+$hashTargets+$entryPoints|Sort-Object -Unique);$orphans=@($eligible|Where-Object{$_.FullName -notin $protected -and $_.FullName -notmatch '(?i)(\\_Audit\\|\\docs\\|\\logs?\\|readme|changelog|version|release|manifest|sha256|checksum)'})
$risks=@();foreach($x in $confirmedMismatch){$risks+=[pscustomobject]@{Severity="P0";FindingId="HASH-MISMATCH";Object=$x.Target;Evidence=("Expected={0};Actual={1};Register={2}" -f $x.ExpectedSHA256,$x.ActualSHA256,$x.Register);Confidence="CONFIRMED"}};foreach($x in @($hv|Where-Object{$_.ResolutionStatus -ne "RESOLVED"})){$risks+=[pscustomobject]@{Severity="P1";FindingId="HASH-REFERENCE";Object=$x.Reference;Evidence=$x.Register;Confidence="HIGH"}};foreach($x in @($ambiguous+$unresolved)){$risks+=[pscustomobject]@{Severity="P1";FindingId="DEPENDENCY-REFERENCE";Object=$x.Reference;Evidence=$x.Source;Confidence="MEDIUM"}};foreach($x in $orphans){$risks+=[pscustomobject]@{Severity="P2";FindingId="ORPHAN-CANDIDATE";Object=$x.FullName;Evidence="No dependency, manifest, hash or entry-point protection.";Confidence="MEDIUM"}}
$p0=@($risks|Where-Object{$_.Severity -eq "P0"});$p1=@($risks|Where-Object{$_.Severity -eq "P1"});$p2=@($risks|Where-Object{$_.Severity -eq "P2"});$decision=if($p0.Count -gt 0){"NO_GO"}elseif($p1.Count -gt 0){"REVIEW_REQUIRED"}elseif($p2.Count -gt 0){"PASS_WITH_WARNINGS"}else{"PASS"}
$disposition=@();foreach($f in $eligible){$rel=Relative-Path $ApplicationRoot $f.FullName;$dup=@($dupes|Where-Object{$_.RelativePath -eq $rel}|Select-Object -First 1);$d="REVIEW";$reason="No confirmed governance coverage.";if($f.FullName -in $protected){$d="KEEP";$reason="Referenced, manifested, hash-listed or entry point."}elseif($f.FullName -match '(?i)\\_Audit\\'){$d="ARCHIVE";$reason="Historical audit evidence."}elseif($dup.Count -gt 0 -and $dup[0].DuplicateType -ne "GOVERNED_OR_EVIDENCE_COPY"){$d="REVIEW";$reason="Exact duplicate requires context."}elseif($f.FullName -in $orphans.FullName){$d="REMOVE_CANDIDATE";$reason="Unreferenced and unprotected; no automatic deletion."};$disposition+=[pscustomobject]@{Disposition=$d;RelativePath=$rel;Category=(Category $f);Reason=$reason}}
$after=@(Get-ChildItem -LiteralPath $ApplicationRoot -File -Recurse -Force|Where-Object{$_.FullName -notlike ($AuditBase+"\*") -and $_.FullName -notlike ($ToolRoot+"\*")}|Sort-Object FullName|ForEach-Object{"{0}|{1}|{2:o}" -f $_.FullName,$_.Length,$_.LastWriteTimeUtc});$sourceUnchanged=(($before|ConvertTo-Json -Compress)-ceq($after|ConvertTo-Json -Compress));if(-not $sourceUnchanged){throw "Source changed during analysis."}
$summary=[ordered]@{Classification=$Classification;Version=$ScriptVersion;RunId=$RunId;Files=$eligible.Count;Folders=$folders.Count;CodeAndConfig=$code.Count;DependencyEdges=$deps.Count;DependencyResolutionPct=if($local.Count){[math]::Round($resolved.Count*100.0/$local.Count,2)}else{100};RuntimeReferenceCount=$runtimes.Count;UniqueRuntimeCount=@($runtimes.Target|Sort-Object -Unique).Count;ManifestArtifactsFound=$manifests.Count;ManifestEntriesParsed=$mr.Count;ManifestEntriesResolved=@($mr|Where-Object{$_.Status -eq "RESOLVED"}).Count;HashRegistersFound=$hashRegisters.Count;HashEntriesParsed=$hv.Count;HashEntriesResolved=@($hv|Where-Object{$_.ResolutionStatus -eq "RESOLVED"}).Count;HashEntriesVerified=@($hv|Where-Object{$_.Verification -eq "MATCH"}).Count;ExactDuplicateGroups=$dupeGroups.Count;OrphanAssets=$orphans.Count;ConfirmedP0Count=$p0.Count;P1Count=$p1.Count;P2Count=$p2.Count;Decision=$decision;SourceUnchanged=$sourceUnchanged}
Write-Host "";Write-Host ("{0} | {1} v{2}" -f $Classification,$ScriptName,$ScriptVersion) -ForegroundColor Cyan;Write-Host ("APPLICATION ROOT: {0}" -f $ApplicationRoot);Write-Host ("PROPOSED TOOL PATH: {0}" -f $InstalledTool);Write-Host ("PROPOSED REPORT ROOT: {0}" -f $ReportRoot);[pscustomobject]$summary|Format-List;$disposition|Group-Object Disposition|Select-Object Name,Count|Format-Table -AutoSize
if($AuditOnly){Write-Host "AUDITONLY PASS: NO FILES OR FOLDERS CREATED." -ForegroundColor Green;exit 0}
foreach($d in @($ToolRoot,$AuditBase,$ReportRoot)){if(-not(Test-Path -LiteralPath $d -PathType Container)){New-Item -ItemType Directory -Path $d -ErrorAction Stop|Out-Null}}
if($PSCommandPath -ne $InstalledTool){Copy-Item -LiteralPath $PSCommandPath -Destination $InstalledTool -Force;if((Get-FileHash $PSCommandPath -Algorithm SHA256).Hash -ne (Get-FileHash $InstalledTool -Algorithm SHA256).Hash){throw "Installed script SHA256 mismatch."}}
$deps|Export-Csv (Join-Path $ReportRoot "Dependency_Graph.csv") -NoTypeInformation -Encoding utf8;$runtimes|Export-Csv (Join-Path $ReportRoot "Runtime_Dependencies.csv") -NoTypeInformation -Encoding utf8;$manifests|Select-Object FullName,Name,Length|Export-Csv (Join-Path $ReportRoot "Manifest_Discovery.csv") -NoTypeInformation -Encoding utf8;$mr|Export-Csv (Join-Path $ReportRoot "Manifest_Entry_Resolution.csv") -NoTypeInformation -Encoding utf8;$hv|Export-Csv (Join-Path $ReportRoot "Hash_Register_Validation.csv") -NoTypeInformation -Encoding utf8;$dupes|Export-Csv (Join-Path $ReportRoot "Duplicate_Analysis.csv") -NoTypeInformation -Encoding utf8;$orphans|Select-Object FullName,Name,Extension,Length|Export-Csv (Join-Path $ReportRoot "Orphan_Assets.csv") -NoTypeInformation -Encoding utf8;$risks|Export-Csv (Join-Path $ReportRoot "Governance_Risk_Register.csv") -NoTypeInformation -Encoding utf8;$disposition|Export-Csv (Join-Path $ReportRoot "Governance_Disposition.csv") -NoTypeInformation -Encoding utf8;@([pscustomobject]$summary)|Export-Csv (Join-Path $ReportRoot "Governance_Executive_Summary.csv") -NoTypeInformation -Encoding utf8;$summary|ConvertTo-Json -Depth 10|Set-Content (Join-Path $ReportRoot "Governance_KPIs.json") -Encoding utf8
$reportFiles=@(Get-ChildItem -LiteralPath $ReportRoot -File);$manifest=[ordered]@{Classification=$Classification;Version=$ScriptVersion;RunId=$RunId;Decision=$decision;Files=@()};foreach($f in $reportFiles){$manifest.Files+=[ordered]@{RelativePath=(Relative-Path $ReportRoot $f.FullName);Length=$f.Length;SHA256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$manifest|ConvertTo-Json -Depth 20|Set-Content (Join-Path $ReportRoot "Manifest.json") -Encoding utf8;$lines=@();foreach($f in @(Get-ChildItem -LiteralPath $ReportRoot -File|Sort-Object FullName)){$lines+=("{0}  {1}" -f (Get-FileHash $f.FullName -Algorithm SHA256).Hash,(Relative-Path $ReportRoot $f.FullName))};$lines|Set-Content (Join-Path $ReportRoot "SHA256SUMS.txt") -Encoding ascii
Write-Host ("INSTALLED CONTROL SCRIPT: {0}" -f $InstalledTool) -ForegroundColor Green;Write-Host ("REPORT ROOT: {0}" -f $ReportRoot) -ForegroundColor Green;Write-Host ("DECISION: {0}" -f $decision);Write-Host "APPLICATION GOVERNANCE CONTROLS COMPLETE" -ForegroundColor Green
